// src/services/compaction.ts
import { existsSync as existsSync4, mkdirSync as mkdirSync2, readdirSync, readFileSync as readFileSync4, writeFileSync as writeFileSync4 } from "node:fs";
import { join as join5 } from "node:path";
import { homedir as homedir5 } from "node:os";

// src/services/compaction-prompt.ts
var COMPACTION_CONTEXT_MARKER = "[SUPERMEMORY COMPACTION CONTEXT]";
var MAX_COMPACTION_MEMORY_CHARS = 12000;
var MAX_SINGLE_MEMORY_CHARS = 2000;
function fitProjectMemories(memories) {
  const result = [];
  const seen = new Set;
  let remaining = MAX_COMPACTION_MEMORY_CHARS;
  for (const rawMemory of memories) {
    const normalized = rawMemory.trim();
    if (!normalized || seen.has(normalized) || remaining <= 0)
      continue;
    seen.add(normalized);
    const memory = normalized.slice(0, Math.min(MAX_SINGLE_MEMORY_CHARS, remaining));
    result.push(memory);
    remaining -= memory.length;
  }
  return result;
}
function createCompactionPrompt(projectMemories) {
  const memoriesSection = projectMemories.length > 0 ? `
## Project Knowledge (from Supermemory)
The following project-specific knowledge should be preserved and referenced in the summary:
${projectMemories.map((memory) => `- ${memory}`).join(`
`)}
` : "";
  return `${COMPACTION_CONTEXT_MARKER}

When summarizing this session, you MUST include the following sections in your summary:

## 1. User Requests (As-Is)
- List all original user requests exactly as they were stated
- Preserve the user's exact wording and intent

## 2. Final Goal
- What the user ultimately wanted to achieve
- The end result or deliverable expected

## 3. Work Completed
- What has been done so far
- Files created/modified
- Features implemented
- Problems solved

## 4. Remaining Tasks
- What still needs to be done
- Pending items from the original request
- Follow-up tasks identified during the work

## 5. MUST NOT Do (Critical Constraints)
- Things that were explicitly forbidden
- Approaches that failed and should not be retried
- User's explicit restrictions or preferences
- Anti-patterns identified during the session
${memoriesSection}
This context is critical for maintaining continuity after compaction.
`;
}

// src/services/compaction.ts
var MESSAGE_STORAGE = join5(homedir5(), ".opencode", "messages");
var PART_STORAGE = join5(homedir5(), ".opencode", "parts");
var DEFAULT_THRESHOLD = 0.8;
var MIN_TOKENS_FOR_COMPACTION = 50000;
var COMPACTION_COOLDOWN_MS = 30000;
var DEFAULT_CONTEXT_LIMIT = 200000;
function getMessageDir(sessionID) {
  if (!existsSync4(MESSAGE_STORAGE))
    return null;
  const directPath = join5(MESSAGE_STORAGE, sessionID);
  if (existsSync4(directPath))
    return directPath;
  for (const dir of readdirSync(MESSAGE_STORAGE)) {
    const sessionPath = join5(MESSAGE_STORAGE, dir, sessionID);
    if (existsSync4(sessionPath))
      return sessionPath;
  }
  return null;
}
function getOrCreateMessageDir(sessionID) {
  if (!existsSync4(MESSAGE_STORAGE)) {
    mkdirSync2(MESSAGE_STORAGE, { recursive: true });
  }
  const directPath = join5(MESSAGE_STORAGE, sessionID);
  if (existsSync4(directPath))
    return directPath;
  for (const dir of readdirSync(MESSAGE_STORAGE)) {
    const sessionPath = join5(MESSAGE_STORAGE, dir, sessionID);
    if (existsSync4(sessionPath))
      return sessionPath;
  }
  mkdirSync2(directPath, { recursive: true });
  return directPath;
}
function findNearestMessageWithFields(messageDir) {
  try {
    const files = readdirSync(messageDir).filter((f) => f.endsWith(".json")).sort().reverse();
    for (const file of files) {
      try {
        const content = readFileSync4(join5(messageDir, file), "utf-8");
        const msg = JSON.parse(content);
        if (msg.agent && msg.model?.providerID && msg.model?.modelID) {
          return msg;
        }
      } catch {
        continue;
      }
    }
  } catch {
    return null;
  }
  return null;
}
function generateMessageId() {
  const timestamp = Date.now().toString(16);
  const random = Math.random().toString(36).substring(2, 14);
  return `msg_${timestamp}${random}`;
}
function generatePartId() {
  const timestamp = Date.now().toString(16);
  const random = Math.random().toString(36).substring(2, 10);
  return `prt_${timestamp}${random}`;
}
function injectHookMessage(sessionID, hookContent, originalMessage) {
  if (!hookContent || hookContent.trim().length === 0) {
    log("[compaction] attempted to inject empty content, skipping");
    return false;
  }
  const messageDir = getOrCreateMessageDir(sessionID);
  const fallback = findNearestMessageWithFields(messageDir);
  const now = Date.now();
  const messageID = generateMessageId();
  const partID = generatePartId();
  const resolvedAgent = originalMessage.agent ?? fallback?.agent ?? "general";
  const resolvedModel = originalMessage.model?.providerID && originalMessage.model?.modelID ? { providerID: originalMessage.model.providerID, modelID: originalMessage.model.modelID } : fallback?.model?.providerID && fallback?.model?.modelID ? { providerID: fallback.model.providerID, modelID: fallback.model.modelID } : undefined;
  const messageMeta = {
    id: messageID,
    sessionID,
    role: "user",
    time: { created: now },
    agent: resolvedAgent,
    model: resolvedModel,
    path: originalMessage.path?.cwd ? { cwd: originalMessage.path.cwd, root: originalMessage.path.root ?? "/" } : undefined
  };
  const textPart = {
    id: partID,
    type: "text",
    text: hookContent,
    synthetic: true,
    time: { start: now, end: now },
    messageID,
    sessionID
  };
  try {
    writeFileSync4(join5(messageDir, `${messageID}.json`), JSON.stringify(messageMeta, null, 2));
    const partDir = join5(PART_STORAGE, messageID);
    if (!existsSync4(partDir)) {
      mkdirSync2(partDir, { recursive: true });
    }
    writeFileSync4(join5(partDir, `${partID}.json`), JSON.stringify(textPart, null, 2));
    log("[compaction] hook message injected", { sessionID, messageID });
    return true;
  } catch (err) {
    log("[compaction] failed to inject hook message", { error: String(err) });
    return false;
  }
}
function createCompactionHook(ctx, tags, options) {
  const state = {
    lastCompactionTime: new Map,
    compactionInProgress: new Set,
    summarizedSessions: new Set
  };
  const threshold = options?.threshold ?? DEFAULT_THRESHOLD;
  const getModelLimit = options?.getModelLimit;
  async function fetchProjectMemoriesForCompaction() {
    try {
      const result = await supermemoryClient.listMemoriesScoped(tags.canonical, tags.projectReads, "project", CONFIG.maxProjectMemories);
      const memories = result.memories || [];
      return memories.map((m) => m.summary || m.content || "").filter(Boolean);
    } catch (err) {
      log("[compaction] failed to fetch project memories", { error: String(err) });
      return [];
    }
  }
  async function injectCompactionContext(summarizeCtx) {
    log("[compaction] injecting context", { sessionID: summarizeCtx.sessionID });
    const projectMemories = await fetchProjectMemoriesForCompaction();
    const prompt = createCompactionPrompt(projectMemories);
    const success = injectHookMessage(summarizeCtx.sessionID, prompt, {
      agent: summarizeCtx.agent,
      model: { providerID: summarizeCtx.providerID, modelID: summarizeCtx.modelID },
      path: { cwd: summarizeCtx.directory }
    });
    if (success) {
      log("[compaction] context injected with project memories", {
        sessionID: summarizeCtx.sessionID,
        memoriesCount: projectMemories.length
      });
    }
  }
  async function saveSummaryAsMemory(sessionID, summaryContent) {
    if (!summaryContent || summaryContent.length < 100) {
      log("[compaction] summary too short to save", { sessionID, length: summaryContent.length });
      return;
    }
    try {
      const result = await supermemoryClient.addMemory(`[Session Summary]
${summaryContent}`, tags.canonical, {
        type: "conversation",
        project: tags.projectName,
        sm_project_id: tags.projectId,
        sm_scope: "personal",
        sm_capture_mode: "compaction",
        sessionId: sessionID
      }, { entityContext: AGENT_ENTITY_CONTEXT });
      if (result.success) {
        log("[compaction] summary saved as memory", { sessionID, memoryId: result.id });
      } else {
        log("[compaction] failed to save summary", { error: result.error });
      }
    } catch (err) {
      log("[compaction] failed to save summary", { error: String(err) });
    }
  }
  async function checkAndTriggerCompaction(sessionID, lastAssistant) {
    if (state.compactionInProgress.has(sessionID))
      return;
    const lastCompaction = state.lastCompactionTime.get(sessionID) ?? 0;
    if (Date.now() - lastCompaction < COMPACTION_COOLDOWN_MS)
      return;
    if (lastAssistant.summary === true)
      return;
    const tokens = lastAssistant.tokens;
    if (!tokens)
      return;
    let modelID = lastAssistant.modelID ?? "";
    let providerID = lastAssistant.providerID ?? "";
    let agent;
    const messageDir = getMessageDir(sessionID);
    const storedMessage = messageDir ? findNearestMessageWithFields(messageDir) : null;
    if (!providerID || !modelID) {
      if (storedMessage?.model?.providerID)
        providerID = storedMessage.model.providerID;
      if (storedMessage?.model?.modelID)
        modelID = storedMessage.model.modelID;
    }
    agent = storedMessage?.agent;
    const configLimit = getModelLimit?.(providerID, modelID);
    const contextLimit = configLimit ?? DEFAULT_CONTEXT_LIMIT;
    const totalUsed = tokens.input + tokens.cache.read + tokens.output;
    if (totalUsed < MIN_TOKENS_FOR_COMPACTION)
      return;
    const usageRatio = totalUsed / contextLimit;
    log("[compaction] checking", {
      sessionID,
      totalUsed,
      contextLimit,
      usageRatio: usageRatio.toFixed(2),
      threshold
    });
    if (usageRatio < threshold)
      return;
    state.compactionInProgress.add(sessionID);
    state.lastCompactionTime.set(sessionID, Date.now());
    if (!providerID || !modelID) {
      state.compactionInProgress.delete(sessionID);
      return;
    }
    await ctx.client.tui.showToast({
      body: {
        title: "Preemptive Compaction",
        message: `Context at ${(usageRatio * 100).toFixed(0)}% - compacting with Supermemory context...`,
        variant: "warning",
        duration: 3000
      }
    }).catch(() => {});
    log("[compaction] triggering compaction", { sessionID, usageRatio });
    try {
      await injectCompactionContext({
        sessionID,
        providerID,
        modelID,
        usageRatio,
        directory: ctx.directory,
        agent
      });
      state.summarizedSessions.add(sessionID);
      await ctx.client.session.summarize({
        path: { id: sessionID },
        body: { providerID, modelID },
        query: { directory: ctx.directory }
      });
      await ctx.client.tui.showToast({
        body: {
          title: "Compaction Complete",
          message: "Session compacted with Supermemory context. Resuming...",
          variant: "success",
          duration: 2000
        }
      }).catch(() => {});
      state.compactionInProgress.delete(sessionID);
      setTimeout(async () => {
        try {
          const messageDir = getMessageDir(sessionID);
          const storedMessage = messageDir ? findNearestMessageWithFields(messageDir) : null;
          await ctx.client.session.promptAsync({
            path: { id: sessionID },
            body: {
              agent: storedMessage?.agent,
              parts: [{ type: "text", text: "Continue" }]
            },
            query: { directory: ctx.directory }
          });
        } catch {}
      }, 500);
    } catch (err) {
      log("[compaction] compaction failed", { sessionID, error: String(err) });
      state.compactionInProgress.delete(sessionID);
    }
  }
  async function handleSummaryMessage(sessionID, _messageInfo) {
    log("[compaction] handleSummaryMessage called", { sessionID, inSet: state.summarizedSessions.has(sessionID) });
    if (!state.summarizedSessions.has(sessionID))
      return;
    state.summarizedSessions.delete(sessionID);
    log("[compaction] capturing summary for memory", { sessionID });
    try {
      const resp = await ctx.client.session.messages({
        path: { id: sessionID },
        query: { directory: ctx.directory }
      });
      const messages = resp.data ?? resp;
      const summaryMessage = messages.find((m) => m.info.role === "assistant" && m.info.summary === true);
      log("[compaction] looking for summary message", {
        sessionID,
        found: !!summaryMessage,
        hasParts: !!summaryMessage?.parts
      });
      if (summaryMessage?.parts) {
        const textParts = summaryMessage.parts.filter((p) => p.type === "text" && p.text);
        const summaryContent = textParts.map((p) => p.text).join(`
`);
        log("[compaction] summary content", {
          sessionID,
          textPartsCount: textParts.length,
          contentLength: summaryContent.length
        });
        if (summaryContent) {
          await saveSummaryAsMemory(sessionID, summaryContent);
        }
      }
    } catch (err) {
      log("[compaction] failed to capture summary", { error: String(err) });
    }
  }
  return {
    async event({ event }) {
      const props = event.properties;
      if (event.type === "session.deleted") {
        const sessionInfo = props?.info;
        if (sessionInfo?.id) {
          state.lastCompactionTime.delete(sessionInfo.id);
          state.compactionInProgress.delete(sessionInfo.id);
          state.summarizedSessions.delete(sessionInfo.id);
        }
        return;
      }
      if (event.type === "message.updated") {
        const info = props?.info;
        if (!info)
          return;
        const sessionID = info.sessionID;
        if (!sessionID)
          return;
        if (info.role === "assistant" && info.summary === true && info.finish) {
          await handleSummaryMessage(sessionID, info);
          return;
        }
        if (info.role !== "assistant" || !info.finish)
          return;
        await checkAndTriggerCompaction(sessionID, info);
        return;
      }
      if (event.type === "session.idle") {
        const sessionID = props?.sessionID;
        if (!sessionID)
          return;
        try {
          const resp = await ctx.client.session.messages({
            path: { id: sessionID },
            query: { directory: ctx.directory }
          });
          const messages = resp.data ?? resp;
          const assistants = messages.filter((m) => m.info.role === "assistant").map((m) => m.info);
          if (assistants.length === 0)
            return;
          const lastAssistant = assistants[assistants.length - 1];
          if (!lastAssistant.providerID || !lastAssistant.modelID) {
            const messageDir = getMessageDir(sessionID);
            const storedMessage = messageDir ? findNearestMessageWithFields(messageDir) : null;
            if (storedMessage?.model?.providerID && storedMessage?.model?.modelID) {
              lastAssistant.providerID = storedMessage.model.providerID;
              lastAssistant.modelID = storedMessage.model.modelID;
            }
          }
          await checkAndTriggerCompaction(sessionID, lastAssistant);
        } catch {}
      }
    }
  };
}

// src/services/version-check.ts
var NPM_REGISTRY_URL = "https://registry.npmjs.org";
var CHECK_TIMEOUT_MS = 3000;
function parseVersion(version) {
  const normalized = version.trim().replace(/^v/i, "");
  const match = normalized.match(/^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?/);
  if (!match)
    return null;
  return {
    parts: [Number(match[1]), Number(match[2]), Number(match[3])],
    prerelease: match[4] ?? null
  };
}
function isVersionNewer(latestVersion, currentVersion) {
  const latest = parseVersion(latestVersion);
  const current = parseVersion(currentVersion);
  if (!latest || !current)
    return latestVersion !== currentVersion;
  for (let i = 0;i < 3; i++) {
    const latestPart = latest.parts[i] ?? 0;
    const currentPart = current.parts[i] ?? 0;
    if (latestPart > currentPart)
      return true;
    if (latestPart < currentPart)
      return false;
  }
  if (!latest.prerelease && current.prerelease)
    return true;
  if (latest.prerelease && !current.prerelease)
    return false;
  return latest.prerelease !== current.prerelease && latest.prerelease !== null;
}
async function checkNpmUpdate(packageName, currentVersion, updateCommand) {
  const controller = new AbortController;
  const timeout = setTimeout(() => controller.abort(), CHECK_TIMEOUT_MS);
  try {
    const encodedPackage = packageName.startsWith("@") ? packageName.replace("/", "%2F") : encodeURIComponent(packageName);
    const response = await fetch(`${NPM_REGISTRY_URL}/${encodedPackage}/latest`, {
      signal: controller.signal
    });
    if (!response.ok)
      return null;
    const data = await response.json();
    const latestVersion = typeof data.version === "string" ? data.version : null;
    if (!latestVersion || !isVersionNewer(latestVersion, currentVersion))
      return null;
    return { currentVersion, latestVersion, updateCommand };
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

// src/index.ts
var CODE_BLOCK_PATTERN = /```[\s\S]*?```/g;
var INLINE_CODE_PATTERN = /`[^`]+`/g;
var MEMORY_KEYWORD_PATTERN = new RegExp(`\\b(${CONFIG.keywordPatterns.join("|")})\\b`, "i");
var MEMORY_NUDGE_MESSAGE = `[MEMORY TRIGGER DETECTED]
The user wants you to remember something. You MUST use the \`supermemory\` tool with \`mode: "add"\` to save this information.

Extract the key information the user wants remembered and save it as a concise, searchable memory.
- Use \`scope: "project"\` for project-specific preferences (e.g., "run lint with tests")
- Use \`scope: "user"\` for personal preferences in this project (e.g., "prefers concise responses")
- Choose an appropriate \`type\`: "preference", "project-config", "learned-pattern", etc.

DO NOT skip this step. The user explicitly asked you to remember.`;
var UPDATE_COMMAND = "bunx opencode-supermemory@latest install";
function removeCodeBlocks(text) {
  return text.replace(CODE_BLOCK_PATTERN, "").replace(INLINE_CODE_PATTERN, "");
}
function detectMemoryKeyword(text) {
  const textWithoutCode = removeCodeBlocks(text);
  return MEMORY_KEYWORD_PATTERN.test(textWithoutCode);
}
function isSupermemoryRecallSearch(input) {
  const type = String(input.type ?? "");
  const title = String(input.title ?? "").toLowerCase();
  const metadata = input.metadata ?? {};
  const toolName = String(metadata.tool ?? metadata.toolName ?? type);
  const isSupermemory = type === "supermemory" || toolName === "supermemory" || title.includes("supermemory");
  if (!isSupermemory)
    return false;
  const args = metadata.args ?? metadata.input ?? metadata.arguments ?? metadata;
  return String(args.mode ?? "") === "search";
}
var SupermemoryPlugin = async (ctx) => {
  const { directory } = ctx;
  const tags = getTags(directory);
  const injectedSessions = new Set;
  const recallSessions = new RecallSessionCache;
  const activity = createMemoryActivityReporter(ctx.client);
  log("Plugin init", { directory, tags, configured: isConfigured() });
  if (!isConfigured()) {
    log("Plugin disabled - SUPERMEMORY_API_KEY not set");
  }
  const modelLimits = new Map;
  (async () => {
    try {
      const response = await ctx.client.provider.list();
      if (response.data?.all) {
        for (const provider of response.data.all) {
          if (provider.models) {
            for (const [modelId, model] of Object.entries(provider.models)) {
              if (model.limit?.context) {
                modelLimits.set(`${provider.id}/${modelId}`, model.limit.context);
              }
            }
          }
        }
      }
      log("Model limits loaded", { count: modelLimits.size });
    } catch (error) {
      log("Failed to fetch model limits", { error: String(error) });
    }
  })();
  const getModelLimit = (providerID, modelID) => {
    return modelLimits.get(`${providerID}/${modelID}`);
  };
  const compactionHook = isConfigured() && ctx.client ? createCompactionHook(ctx, tags, {
    threshold: CONFIG.compactionThreshold,
    getModelLimit
  }) : null;
  const captureHook = isConfigured() && ctx.client ? createCaptureHook(ctx, tags, { onSaved: () => activity.saved() }) : null;
  return {
    "chat.message": async (input, output) => {
      if (!isConfigured())
        return;
      const start = Date.now();
      try {
        const textParts = output.parts.filter((p) => p.type === "text");
        if (textParts.length === 0) {
          log("chat.message: no text parts found");
          return;
        }
        const userMessage = textParts.map((p) => p.text).join(`
`);
        if (!userMessage.trim()) {
          log("chat.message: empty message, skipping");
          return;
        }
        log("chat.message: processing", {
          messagePreview: userMessage.slice(0, 100),
          partsCount: output.parts.length,
          textPartsCount: textParts.length
        });
        if (detectMemoryKeyword(userMessage)) {
          log("chat.message: memory keyword detected");
          const nudgePart = {
            id: `prt_supermemory-nudge-${Date.now()}`,
            sessionID: input.sessionID,
            messageID: output.message.id,
            type: "text",
            text: MEMORY_NUDGE_MESSAGE,
            synthetic: true
          };
          output.parts.push(nudgePart);
        }
        const isFirstMessage = !injectedSessions.has(input.sessionID);
        if (isFirstMessage)
          injectedSessions.add(input.sessionID);
        if (CONFIG.recallMode === "advisory") {
          output.parts.push({
            id: `prt_supermemory-recall-${Date.now()}`,
            sessionID: input.sessionID,
            messageID: output.message.id,
            type: "text",
            text: buildRecallDirective(),
            synthetic: true
          });
        }
        const profileRequest = isFirstMessage && CONFIG.recallMode !== "off" && CONFIG.injectProfile ? supermemoryClient.getProfileScoped(tags.canonical, tags.personalReads, "personal", undefined, { timeoutMs: DIRECT_RECALL_TIMEOUT_MS }) : Promise.resolve(null);
        const directRecallPromise = CONFIG.recallMode === "direct" ? buildDirectRecallResult({
          prompt: userMessage,
          sessionID: input.sessionID,
          cache: recallSessions,
          search: (query) => supermemoryClient.searchMemoriesForRecall(query, tags.canonical, tags.personalReads, tags.projectReads, { timeoutMs: DIRECT_RECALL_TIMEOUT_MS }),
          suppressTexts: isFirstMessage ? profileRequest.then((result) => result?.success && result.profile ? getInjectedProfileFactTexts(result) : []) : undefined
        }) : Promise.resolve({
          context: "",
          status: "skipped",
          count: 0,
          tokens: 0
        });
        const firstMessage = isFirstMessage ? profileRequest.then((profileResult) => {
          const profile = profileResult?.success ? profileResult : null;
          return profile ? formatContextForPrompt(profile, { results: [] }, { results: [] }) : "";
        }) : Promise.resolve("");
        const updateCheck = isFirstMessage ? checkNpmUpdate("opencode-supermemory", PLUGIN_VERSION, UPDATE_COMMAND) : Promise.resolve(null);
        const [directRecall, firstMessageContext, updateInfo] = await Promise.all([
          directRecallPromise,
          firstMessage,
          updateCheck
        ]);
        if (directRecall.status === "recalled") {
          activity.recalled(directRecall.count, directRecall.tokens);
        } else if (directRecall.status === "unavailable") {
          activity.recallUnavailable();
        }
        if (updateInfo)
          activity.updateAvailable(updateInfo);
        if (firstMessageContext) {
          output.parts.unshift({
            id: `prt_supermemory-context-${Date.now()}`,
            sessionID: input.sessionID,
            messageID: output.message.id,
            type: "text",
            text: firstMessageContext,
            synthetic: true
          });
        }
        if (directRecall.context) {
          output.parts.push({
            id: `prt_supermemory-direct-recall-${Date.now()}`,
            sessionID: input.sessionID,
            messageID: output.message.id,
            type: "text",
            text: directRecall.context,
            synthetic: true,
            metadata: {
              supermemory: {
                activity: "recalled",
                count: directRecall.count,
                tokens: directRecall.tokens
              }
            }
          });
        }
        log("chat.message: context processed", {
          duration: Date.now() - start,
          firstMessageContextLength: firstMessageContext.length,
          directRecallContextLength: directRecall.context.length
        });
      } catch (error) {
        log("chat.message: ERROR", { error: String(error) });
      }
    },
    tool: {
      supermemory: tool({
        description: SUPERMEMORY_TOOL_DESCRIPTION,
        args: {
          mode: tool.schema.enum(MEMORY_TOOL_MODES).optional(),
          content: tool.schema.string().optional(),
          query: tool.schema.string().optional(),
          type: tool.schema.enum(MEMORY_TOOL_TYPES).optional(),
          scope: tool.schema.enum(MEMORY_TOOL_SCOPES).optional(),
          memoryId: tool.schema.string().optional(),
          limit: tool.schema.number().optional()
        },
        async execute(args) {
          return executeSupermemoryTool(args, tags, {
            onSaved: () => activity.saved()
          });
        }
      })
    },
    "permission.ask": async (input, output) => {
      if (!isConfigured())
        return;
      try {
        if (isSupermemoryRecallSearch(input)) {
          output.status = "allow";
          log("permission.ask: auto-allowing supermemory recall search");
        }
      } catch (error) {
        log("permission.ask: ERROR", { error: String(error) });
      }
    },
    "tool.execute.before": async (input, output) => {
      if (input.tool !== "supermemory")
        return;
      const args = output.args;
      if (args.mode === "search") {
        activity.recalling(typeof args.query === "string" ? args.query : undefined);
      }
    },
    "tool.execute.after": async (input, output) => {
      if (input.tool !== "supermemory")
        return;
      try {
        const result = JSON.parse(output.output);
        if (!result.success)
          return;
        const count = result.count ?? result.results?.length;
        if (typeof count === "number" && count > 0) {
          activity.recalled(count, Math.round(output.output.length / 4));
        }
      } catch {}
    },
    event: async (input) => {
      const props = input.event.properties;
      if (input.event.type === "session.deleted") {
        const sessionID = props?.info?.id;
        if (sessionID) {
          injectedSessions.delete(sessionID);
          recallSessions.delete(sessionID);
        }
      } else if (input.event.type === "server.instance.disposed") {
        injectedSessions.clear();
        recallSessions.clear();
      }
      if (compactionHook) {
        await compactionHook.event(input);
      }
      if (captureHook) {
        if (input.event.type === "session.idle") {
          captureHook.event(input).catch((error) => {
            log("[capture] background idle capture failed", {
              error: String(error)
            });
          });
        } else {
          await captureHook.event(input);
        }
      }
    }
  };
};
export {
  MEMORY_NUDGE_MESSAGE,
  SupermemoryPlugin,
  UPDATE_COMMAND
};
